CREATE DATABASE IF NOT EXISTS oracle_corpus;
USE oracle_corpus;
CREATE TABLE IF NOT EXISTS customers (c_id INT NOT NULL, c_name VARCHAR(32) NOT NULL, c_region INT NOT NULL, c_segment VARCHAR(8) NOT NULL) ENGINE=OLAP DUPLICATE KEY (c_id) DISTRIBUTED BY HASH(c_id) BUCKETS 4 PROPERTIES ('replication_num'='1');
CREATE TABLE IF NOT EXISTS products (p_id INT NOT NULL, p_category INT NOT NULL, p_brand VARCHAR(16) NOT NULL, p_price DECIMAL(10,2) NOT NULL) ENGINE=OLAP DUPLICATE KEY (p_id) DISTRIBUTED BY HASH(p_id) BUCKETS 2 PROPERTIES ('replication_num'='1');
CREATE TABLE IF NOT EXISTS sales (s_id BIGINT NOT NULL, s_date DATE NOT NULL, s_cust INT NOT NULL, s_prod INT NOT NULL, s_qty INT NOT NULL, s_amount DECIMAL(12,2) NOT NULL) ENGINE=OLAP DUPLICATE KEY (s_id) DISTRIBUTED BY HASH(s_id) BUCKETS 8 PROPERTIES ('replication_num'='1');
CREATE TABLE IF NOT EXISTS returns (r_id BIGINT NOT NULL, r_sale BIGINT NOT NULL, r_cust INT NOT NULL, r_amount DECIMAL(12,2) NOT NULL) ENGINE=OLAP DUPLICATE KEY (r_id) DISTRIBUTED BY HASH(r_id) BUCKETS 4 PROPERTIES ('replication_num'='1');
CREATE TABLE IF NOT EXISTS events (e_id BIGINT NOT NULL, e_cust INT NOT NULL, e_type VARCHAR(16) NOT NULL, e_ts DATETIME NOT NULL, e_value INT NOT NULL) ENGINE=OLAP DUPLICATE KEY (e_id) DISTRIBUTED BY HASH(e_id) BUCKETS 4 PROPERTIES ('replication_num'='1');
INSERT INTO customers SELECT CAST(g AS INT), concat('cust_', CAST(g AS VARCHAR)), CAST(g % 25 AS INT), CASE g % 4 WHEN 0 THEN 'A' WHEN 1 THEN 'B' WHEN 2 THEN 'C' ELSE 'D' END FROM (SELECT CAST(generate_series AS BIGINT) AS g FROM TABLE(generate_series(1, 20000))) x;
INSERT INTO products SELECT CAST(g AS INT), CAST(g % 40 AS INT), concat('brand_', CAST(g % 100 AS VARCHAR)), CAST((g % 1000) + 0.99 AS DECIMAL(10,2)) FROM (SELECT CAST(generate_series AS BIGINT) AS g FROM TABLE(generate_series(1, 5000))) x;
INSERT INTO sales SELECT g, date_add('2024-01-01', CAST(g % 365 AS INT)), CAST((g * 7919) % 20000 + 1 AS INT), CAST((g * 104729) % 5000 + 1 AS INT), CAST(g % 10 + 1 AS INT), CAST(((g * 31) % 10000) / 100.0 AS DECIMAL(12,2)) FROM (SELECT CAST(generate_series AS BIGINT) AS g FROM TABLE(generate_series(1, 200000))) x;
INSERT INTO returns SELECT g, g * 10, CAST(((g * 10) * 7919) % 20000 + 1 AS INT), CAST(((g * 17) % 5000) / 100.0 AS DECIMAL(12,2)) FROM (SELECT CAST(generate_series AS BIGINT) AS g FROM TABLE(generate_series(1, 20000))) x;
INSERT INTO events SELECT g, CAST((g * 31) % 20000 + 1 AS INT), CASE g % 3 WHEN 0 THEN 'click' WHEN 1 THEN 'view' ELSE 'purchase' END, seconds_add('2024-01-01 00:00:00', CAST(g AS INT)), CAST(g % 100 AS INT) FROM (SELECT CAST(generate_series AS BIGINT) AS g FROM TABLE(generate_series(1, 100000))) x;
ANALYZE FULL TABLE customers WITH SYNC MODE;
ANALYZE FULL TABLE products WITH SYNC MODE;
ANALYZE FULL TABLE sales WITH SYNC MODE;
ANALYZE FULL TABLE returns WITH SYNC MODE;
ANALYZE FULL TABLE events WITH SYNC MODE;
SELECT 'customers', COUNT(*) FROM customers UNION ALL SELECT 'products', COUNT(*) FROM products UNION ALL SELECT 'sales', COUNT(*) FROM sales UNION ALL SELECT 'returns', COUNT(*) FROM returns UNION ALL SELECT 'events', COUNT(*) FROM events;
